    def test_paths_to_lint_returns_correct_number_of_paths(self):
        """Test that the method returns the same number of paths as directories."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=["dir1", "dir2", "dir3"]
        )
        package.clone_directory = Path("/test/clone/dir")
        result = package.paths_to_lint()
        self.assertEqual(len(result), len(package.directories))

    def test_paths_to_lint_returns_correct_paths(self):
        """Test that the method returns correct full paths."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=["dir1", "dir2", "dir3"]
        )
        package.clone_directory = Path("/test/clone/dir")
        expected_paths = [
            str(Path("/test/clone/dir") / "dir1"),
            str(Path("/test/clone/dir") / "dir2"),
            str(Path("/test/clone/dir") / "dir3"),
        ]
        result = package.paths_to_lint()
        self.assertEqual(result, expected_paths)

    def test_paths_to_lint_with_empty_directories(self):
        """Test that the method returns empty list when directories is empty."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=[]
        )
        package.clone_directory = Path("/test/clone/dir")
        result = package.paths_to_lint()
        self.assertEqual(result, [])

    def test_paths_to_lint_with_single_directory(self):
        """Test that the method works correctly with single directory."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=["single_dir"]
        )
        package.clone_directory = Path("/test/clone/dir")
        expected_path = [str(Path("/test/clone/dir") / "single_dir")]
        result = package.paths_to_lint()
        self.assertEqual(result, expected_path)

    def test_paths_to_lint_does_not_modify_original_directories(self):
        """Test that the method doesn't modify the original directories list."""
