            url="test_url",
            branch="main",
            directories=["dir1", "dir2"]
        )
        package.clone_directory = Path("/test/clone/dir")
        original_directories = package.directories.copy()
        _ = package.paths_to_lint()
        self.assertEqual(package.directories, original_directories)

    def test_paths_to_lint_returns_strings(self):
        """Test that the method returns a list of strings."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=["dir1", "dir2", "dir3"]
        )
        package.clone_directory = Path("/test/clone/dir")
        result = package.paths_to_lint()
        for path in result:
            self.assertIsInstance(path, str)

    def test_paths_to_lint_path_construction_correct(self):
        """Test that the path construction is correct for each directory."""
        package = PackageToLint(
            url="test_url",
            branch="main",
            directories=["dir1", "dir2", "dir3"]
        )
        package.clone_directory = Path("/test/clone/dir")
        result = package.paths_to_lint()
        for i, directory in enumerate(package.directories):
            expected_path = str(package.clone_directory / directory)
            self.assertEqual(result[i], expected_path)

    def test_paths_to_lint_with_different_path_types(self):
