class TestPackageToLintLazyClone(unittest.TestCase):
    def setUp(self):
        self.temp_dir = tempfile.mkdtemp()
        self.clone_dir = Path(self.temp_dir) / "clone"
        self.url = "https://github.com/example/repo.git"
        self.branch = "main"
        self.directories = ["dir1", "dir2"]

        self.package = PackageToLint(
            url=self.url,
            branch=self.branch,
            directories=self.directories,
            commit=None,
            pylint_additional_args=[],
            pylintrc_relpath=None,
            minimum_python=None
        )

    def tearDown(self):
        shutil.rmtree(self.temp_dir)

    @patch.object(PackageToLint, 'clone_directory', new_callable=PropertyMock)
    @patch.object(PackageToLint, '_clone_repository')
    @patch.object(PackageToLint, '_pull_repository')
    def test_lazy_clone_when_directory_does_not_exist(self, mock_pull, mock_clone, mock_clone_dir):
        mock_clone_dir.return_value.exists.return_value = False
        mock_clone.return_value = "Clone output"

        result = self.package.lazy_clone()

        mock_clone_dir.return_value.exists.assert_called_once()
        mock_clone.assert_called_once()
        mock_pull.assert_not_called()
        self.assertEqual(result, "Clone output")

    @patch.object(PackageToLint, 'clone_directory', new_callable=PropertyMock)
    @patch.object(PackageToLint, '_clone_repository')
    @patch.object(PackageToLint, '_pull_repository')
    def test_lazy_clone_when_directory_exists(self, mock_pull, mock_clone, mock_clone_dir):
        mock_clone_dir.return_value.exists.return_value = True
        mock_pull.return_value = "Pull output"

        result = self.package.lazy_clone()

        mock_clone_dir.return_value.exists.assert_called_once()
        mock_clone.assert_not_called()
        mock_pull.assert_called_once()
        self.assertEqual(result, "Pull output")

    @patch.object(PackageToLint, 'clone_directory', new_callable=PropertyMock)
    @patch.object(PackageToLint, '_clone_repository')
    @patch.object(PackageToLint, '_pull_repository')
    def test_lazy_clone_calls_exist_once(self, mock_pull, mock_clone, mock_clone_dir):
        mock_clone_dir.return_value.exists.return_value = True

        self.package.lazy_clone()

        mock_clone_dir.return_value.exists.assert_called_once()

    @patch.object(PackageToLint, 'clone_directory', new_callable=PropertyMock)
    @patch.object(PackageToLint, '_clone_repository')
    @patch.object(PackageToLint, '_pull_repository')
    def test_lazy_clone_returns_clone_output(self, mock_pull, mock_clone, mock_clone_dir):
        mock_clone_dir.return_value.exists.return_value = False
        mock_clone.return_value = "Successfully cloned repository"

        result = self.package.lazy_clone()

        self.assertEqual(result, "Successfully cloned repository")

    @patch.object(PackageToLint, 'clone_directory', new_callable=PropertyMock)
    @patch.object(PackageToLint, '_clone_repository')
    @patch.object(PackageToLint, '_pull_repository')
    def test_lazy_clone_returns_pull_output(self, mock_pull, mock_clone, mock_clone_dir):
