        self.mock_linter = Mock()
        self.mock_linter.config = Mock()
        self.mock_linter._register_options_provider = Mock()

        # Create checker with proper initialization
        self.checker = DunderCallChecker(self.mock_linter)
        self.checker._dunder_methods = {}

    def test_open_with_py37(self):
        """Test initialization with Python 3.7 configuration."""
        self.checker.linter.config.py_version = (3, 7)

        with patch('pylint.checkers.dunder_methods.DUNDER_METHODS', {
            (3, 7): {'__aenter__', '__aexit__'},
            (3, 8): {'__index__'},
            (3, 9): {'__class_getitem__'}
        }):
            self.checker.open()

        self.assertEqual(self.checker._dunder_methods, {'__aenter__', '__aexit__'})

    def test_open_with_py38(self):
        """Test initialization with Python 3.8 configuration."""
        self.checker.linter.config.py_version = (3, 8)

        with patch('pylint.checkers.dunder_methods.DUNDER_METHODS', {
            (3, 7): {'__aenter__'},
            (3, 8): {'__index__', '__length_hint__'},
            (3, 9): {'__class_getitem__'}
        }):
            self.checker.open()

        self.assertEqual(self.checker._dunder_methods, {'__index__', '__length_hint__'})

    def test_open_with_py39(self):
        """Test initialization with Python 3.9 configuration."""
        self.checker.linter.config.py_version = (3, 9)

        with patch('pylint.checkers.dunder_methods.DUNDER_METHODS', {
            (3, 7): {'__aenter__'},
            (3, 8): {'__index__'},
            (3, 9): {'__class_getitem__', '__orig_class__'}
        }):
            self.checker.open()

        self.assertEqual(self.checker._dunder_methods, {'__class_getitem__', '__orig_class__'})

    def test_open_with_multiple_versions(self):
        """Test initialization when multiple version entries apply."""
