        with patch('pylint.checkers.dunder_methods.DUNDER_METHODS', {
            (3, 7): {'__aenter__'},
            (3, 8): {'__index__'},
            (3, 8, 1): {'__special_added_in_patch__'},
            (3, 9): {'__class_getitem__'}
        }):
            self.checker.open()

        self.assertEqual(self.checker._dunder_methods, {'__index__'})

